  "type_id" "int" NOT NULL DEFAULT 2,
  "latitude" "numeric",
  "longitude" "numeric",
  "huge_number" "numeric",
  "number_of_book_reviews" "int" NOT NULL DEFAULT 0,
  "group_id" "int",
  "deleted_at" "timestamp with time zone",
  "titles_of_favorite_books" "text",
  "book_advance_titles_snapshot" "text",
  "number_of_book_advances_snapshot" "text",
  "base_sync_default" "text" NOT NULL,
  "base_async_default" "text" NOT NULL,
  "created_at" "timestamp with time zone" NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updated_at" "timestamp with time zone" NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "favorite_author_id" "int",
  "favorite_author_name" "text",
  "spotlight_author_id" "int",
  "rating" "int",
  FOREIGN KEY ("favorite_author_id") REFERENCES "authors" ("id") ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("group_id") REFERENCES "publisher_groups" ("id") ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("size_id") REFERENCES "publisher_size" ("id") ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("spotlight_author_id") REFERENCES "authors" ("id") ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("type_id") REFERENCES "publisher_type" ("id") ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
);

